const fs = require('fs');
const http = require('http');

// Read and parse the .env.test file
const envContent = fs.readFileSync('.env.test', 'utf8');

// Parse environment variables
const envVars = {};
envContent.split('\n').forEach(line => {
  line = line.trim();
  // Skip empty lines and comments
  if (line && !line.startsWith('#')) {
    const [key, ...valueParts] = line.split('=');
    const value = valueParts.join('=');
    if (key) {
      envVars[key] = value || '';
    }
  }
});

// Prepare the JSON payload
const jsonData = JSON.stringify(envVars, null, 2);

console.log('Environment variables to export:');
console.log(jsonData);

// POST to the documentation API
const postData = JSON.stringify(envVars);

const options = {
  hostname: 'localhost',
  port: 47301,
  path: '/api/doc-export',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(postData)
  }
};

const req = http.request(options, (res) => {
  let responseData = '';

  res.on('data', (chunk) => {
    responseData += chunk;
  });

  res.on('end', () => {
    console.log(`\nResponse status: ${res.statusCode}`);
    console.log('Response body:', responseData);

    if (res.statusCode >= 200 && res.statusCode < 300) {
      console.log('\n✓ Successfully exported environment variables to documentation wiki');
    } else {
      console.log('\n✗ Failed to export environment variables');
    }
  });
});

req.on('error', (error) => {
  console.error('Error making request:', error.message);
});

req.write(postData);
req.end();

