const fs = require('fs');
const https = require('https');
const http = require('http');

// Read and parse the .env.test file
function parseEnvFile(filePath) {
  const content = fs.readFileSync(filePath, 'utf8');
  const envVars = {};

  content.split('\n').forEach(line => {
    line = line.trim();
    // Skip empty lines and comments
    if (line && !line.startsWith('#')) {
      const [key, ...valueParts] = line.split('=');
      const value = valueParts.join('=');
      if (key && value) {
        envVars[key.trim()] = value.trim();
      }
    }
  });

  return envVars;
}

// Function to make HTTP POST request
function postData(url, data) {
  return new Promise((resolve, reject) => {
    const urlObj = new URL(url);
    const isHttps = urlObj.protocol === 'https:';
    const client = isHttps ? https : http;

    const postData = JSON.stringify(data);

    const options = {
      hostname: urlObj.hostname,
      port: urlObj.port,
      path: urlObj.path,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    const req = client.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        try {
          const response = JSON.parse(responseData);
          resolve({ statusCode: res.statusCode, body: response });
        } catch (error) {
          resolve({ statusCode: res.statusCode, body: responseData });
        }
      });
    });

    req.on('error', (error) => {
      reject(error);
    });

    req.write(postData);
    req.end();
  });
}

// Main execution
async function main() {
  try {
    console.log('Reading .env.test file...');
    const envVars = parseEnvFile('.env.test');
    console.log(`Found ${Object.keys(envVars).length} environment variables`);

    const targetUrl = 'http://localhost:47301/api/doc-export';
    console.log(`POSTing to ${targetUrl}...`);

    const result = await postData(targetUrl, envVars);
    console.log(`Response status: ${result.statusCode}`);
    console.log('Response body:', JSON.stringify(result.body, null, 2));

  } catch (error) {
    console.error('Error:', error.message);
    process.exit(1);
  }
}

main();

